import { ok, fail } from './result.js';
import { getCustomer, normalizeId, TIER_DISCOUNTS } from './customers.js';
import { getProduct } from './catalogue.js';
import { roundCents } from './money.js';
import { nextInvoiceNumber } from './numbering.js';
import { isValidDate, addDays } from './dates.js';

/**
 * Calculate the due date based on payment terms and issue date.
 * @param {string} issueDate Date in YYYY-MM-DD format
 * @param {string} terms Payment terms: 'NET14', 'NET30', or 'EOM'
 * @returns {string | null} Due date in YYYY-MM-DD format, or null if terms are invalid
 */
function calculateDueDate(issueDate, terms) {
  if (terms === 'NET14') {
    return addDays(issueDate, 14);
  }
  if (terms === 'NET30') {
    return addDays(issueDate, 30);
  }
  if (terms === 'EOM') {
    // Due on the last day of the issue month
    const [year, month] = issueDate.split('-');
    const currentMonth = parseInt(month);
    const currentYear = parseInt(year);

    // Get last day of the month by going to day 1 of next month and subtracting 1 day
    let nextMonth = currentMonth + 1;
    let nextYear = currentYear;
    if (nextMonth > 12) {
      nextMonth = 1;
      nextYear = currentYear + 1;
    }

    const firstOfNextMonth = `${String(nextYear).padStart(4, '0')}-${String(nextMonth).padStart(2, '0')}-01`;
    return addDays(firstOfNextMonth, -1);
  }
  return null;
}

/**
 * Create a new draft invoice.
 * @param {{ customerId: string, issueDate: string, lines: Array<{ sku: string, qty: number, discountPercent?: number }>, terms?: string }}
 * @returns {{ ok: true, value: { customerId: string, issueDate: string, status: string, lines: Array<{ sku: string, name: string, qty: number, unitPrice: number, vatRate: number, discountPercent?: number }>, terms?: string, dueDate?: string } } | { ok: false, error: string }}
 */
export function createInvoice({ customerId, issueDate, lines, terms = 'NET30' }) {
  // Normalize customer ID
  const normalizedCustomerId = normalizeId(customerId);

  // Validate customer exists
  const customerResult = getCustomer(normalizedCustomerId);
  if (!customerResult.ok) {
    return customerResult;
  }

  const customer = customerResult.value;

  // Validate issueDate is a valid date in YYYY-MM-DD format
  if (!isValidDate(issueDate)) {
    return fail('DATE_INVALID');
  }

  // Validate payment terms
  const dueDate = calculateDueDate(issueDate, terms);
  if (!dueDate) {
    return fail('TERMS_INVALID');
  }

  // Validate lines is not empty
  if (!Array.isArray(lines) || lines.length === 0) {
    return fail('NO_LINES');
  }

  // Get tier discount
  const tierDiscount = TIER_DISCOUNTS[customer.tier] ?? 0;

  // Validate and enrich lines
  const enrichedLines = [];
  for (const line of lines) {
    // Validate qty is a positive integer
    if (!Number.isInteger(line.qty) || line.qty <= 0) {
      return fail('QTY_INVALID');
    }

    // Validate discount if present
    if (line.discountPercent !== undefined) {
      if (typeof line.discountPercent !== 'number' || line.discountPercent < 0 || line.discountPercent > 100) {
        return fail('DISCOUNT_INVALID');
      }
    }

    // Validate sku exists and get product details
    const productResult = getProduct(line.sku);
    if (!productResult.ok) {
      return productResult;
    }

    const product = productResult.value;
    const enrichedLine = {
      sku: line.sku,
      name: product.name,
      qty: line.qty,
      unitPrice: product.unitPrice,
      vatRate: product.vatRate,
    };

    // Apply discount: line's own discountPercent (even 0) wins, otherwise use tier discount
    const discount = line.discountPercent !== undefined ? line.discountPercent : tierDiscount;
    if (discount > 0) {
      enrichedLine.discountPercent = discount;
    }

    enrichedLines.push(enrichedLine);
  }

  const invoice = {
    customerId: normalizedCustomerId,
    issueDate,
    status: 'draft',
    terms,
    dueDate,
    lines: enrichedLines,
  };

  return ok(invoice);
}

/**
 * Calculate the total for a single invoice line.
 * @param {{ qty: number, unitPrice: number }}
 * @returns {number} Total in cents
 */
export function lineTotal(line) {
  return roundCents(line.qty * line.unitPrice);
}

/**
 * Calculate the discount amount for a single invoice line.
 * @param {{ qty: number, unitPrice: number, discountPercent?: number }}
 * @returns {number} Discount amount in cents
 */
export function lineDiscount(line) {
  if (!line.discountPercent) {
    return 0;
  }
  const total = lineTotal(line);
  const discount = roundCents(total * line.discountPercent / 100);
  return Math.max(0, discount);
}

/**
 * Calculate the VAT amount for a single invoice line (VAT is on the amount after discount).
 * @param {{ qty: number, unitPrice: number, vatRate: number, discountPercent?: number }}
 * @returns {number} VAT amount in cents
 */
export function lineVAT(line) {
  const lineAmountTotal = lineTotal(line);
  const discountAmount = lineDiscount(line);
  const lineAmountAfterDiscount = Math.max(0, lineAmountTotal - discountAmount);
  const vat = roundCents(lineAmountAfterDiscount * line.vatRate / 100);
  return Math.max(0, vat);
}

/**
 * Calculate subtotal, discount, VAT and total for an invoice.
 * @param {{ lines: Array<{ qty: number, unitPrice: number, vatRate: number, discountPercent?: number }> }}
 * @returns {{ subtotal: number, discount: number, vat: number, total: number }} Amounts in cents
 */
export function invoiceTotals(invoice) {
  const subtotal = roundCents(invoice.lines.reduce((sum, line) => sum + lineTotal(line), 0));
  const discount = roundCents(invoice.lines.reduce((sum, line) => sum + lineDiscount(line), 0));
  const vat = roundCents(invoice.lines.reduce((sum, line) => sum + lineVAT(line), 0));
  const total = Math.max(0, roundCents(subtotal - discount + vat));
  return { subtotal, discount, vat, total };
}

/**
 * Add or update a line on a draft invoice.
 * @param {{ status: string, customerId: string, issueDate: string, lines: Array }} invoice
 * @param {{ sku: string, qty: number, discountPercent?: number }}
 * @returns {{ ok: true, value: any } | { ok: false, error: string }}
 */
export function addLine(invoice, { sku, qty, discountPercent }) {
  // Check if invoice is draft
  if (invoice.status !== 'draft') {
    return fail('NOT_DRAFT');
  }

  // Validate qty is a positive integer
  if (!Number.isInteger(qty) || qty <= 0) {
    return fail('QTY_INVALID');
  }

  // Validate discount if present
  if (discountPercent !== undefined) {
    if (typeof discountPercent !== 'number' || discountPercent < 0 || discountPercent > 100) {
      return fail('DISCOUNT_INVALID');
    }
  }

  // Validate sku exists
  const productResult = getProduct(sku);
  if (!productResult.ok) {
    return productResult;
  }

  const product = productResult.value;
  const newLines = invoice.lines.map((line) => ({ ...line }));

  // Find if SKU already exists
  const existingLineIndex = newLines.findIndex((line) => line.sku === sku);

  if (existingLineIndex >= 0) {
    // Update existing line
    newLines[existingLineIndex] = {
      ...newLines[existingLineIndex],
      qty: newLines[existingLineIndex].qty + qty,
    };
    if (discountPercent !== undefined) {
      newLines[existingLineIndex].discountPercent = discountPercent;
    }
  } else {
    // Add new line
    const newLine = {
      sku,
      name: product.name,
      qty,
      unitPrice: product.unitPrice,
      vatRate: product.vatRate,
    };
    if (discountPercent !== undefined) {
      newLine.discountPercent = discountPercent;
    }
    newLines.push(newLine);
  }

  const newInvoice = {
    customerId: invoice.customerId,
    issueDate: invoice.issueDate,
    status: invoice.status,
    lines: newLines,
  };

  return ok(newInvoice);
}

/**
 * Remove a line from a draft invoice.
 * @param {{ status: string, customerId: string, issueDate: string, lines: Array }} invoice
 * @param {string} sku
 * @returns {{ ok: true, value: any } | { ok: false, error: string }}
 */
export function removeLine(invoice, sku) {
  // Check if invoice is draft
  if (invoice.status !== 'draft') {
    return fail('NOT_DRAFT');
  }

  // Find the line with the given SKU
  const lineIndex = invoice.lines.findIndex((line) => line.sku === sku);

  if (lineIndex < 0) {
    return fail('LINE_NOT_FOUND');
  }

  // Check if it's the last line
  if (invoice.lines.length === 1) {
    return fail('NO_LINES');
  }

  // Create new invoice without the line
  const newLines = invoice.lines.filter((_, index) => index !== lineIndex);

  const newInvoice = {
    customerId: invoice.customerId,
    issueDate: invoice.issueDate,
    status: invoice.status,
    lines: newLines,
  };

  return ok(newInvoice);
}

/**
 * Issue a draft invoice, assigning it a number and changing status to 'issued'.
 * @param {{ status: string, customerId: string, issueDate: string, lines: Array }} invoice
 * @param {string[]} existingNumbers Array of existing invoice numbers
 * @returns {{ ok: true, value: any } | { ok: false, error: string }}
 */
export function issueInvoice(invoice, existingNumbers) {
  // Check if invoice is draft
  if (invoice.status !== 'draft') {
    return fail('NOT_DRAFT');
  }

  // Get the next invoice number
  const number = nextInvoiceNumber(existingNumbers, invoice.issueDate);

  const newInvoice = {
    customerId: invoice.customerId,
    issueDate: invoice.issueDate,
    status: 'issued',
    number,
    lines: invoice.lines.map((line) => ({ ...line })),
  };

  return ok(newInvoice);
}

